import sys; sys.path.insert(0,'/app')
from seqs import SEQS
def rc(s):
    c={'A':'T','T':'A','G':'C','C':'G'}
    return ''.join(c[b] for b in reversed(s))
out=SEQS['output']
def best_sub(part, out):
    # longest substring of part in out
    best=(0,-1,-1)
    n=len(part)
    for L in range(n,0,-1):
        found=False
        for i in range(0,n-L+1):
            j=out.find(part[i:i+L])
            if j!=-1:
                return (L,i,j)
        # break early optional
    return best
for part in ['egfp','flag','snap']:
    s=SEQS[part]
    L,i,j=best_sub(s,out)
    print(part,'LCS len',L,'part_idx',i,'out_idx',j)
    print('   part around:',s[max(0,i-5):i+L+5])
    print('   out  around:',out[max(0,j-5):j+L+5])
